from functools import reduce


def vektoraddition(v, w):
    return list(map(lambda a, b: a + b, v, w))


def durchschnitt(zahlen):
    return reduce(lambda a, b: a + b, zahlen) / len(zahlen)


print(vektoraddition([1, 2, 3], [10, 20, 30]))   # [11, 22, 33]
print(durchschnitt([1, 2, 3, 4]))                # 2.5

