from functools import reduce


def anzahl_pechrunden(runden):
    return len(list(filter(lambda r: r[-1] == 1, runden)))


def laengste_runde(runden):
    return reduce(lambda a, b: a if a > b else b, map(len, runden))


def gerade_wuerfe(runden):
    return reduce(lambda a, b: a + b,
                  map(lambda r: len(list(filter(lambda w: w % 2 == 0, r))), runden),
                  0)

from functools import reduce


def geburtstagsparadox(n):
    return 1 - reduce(lambda p, k: p * (365 - k) / 365, range(n), 1.0)
